دالة ثنائي(ع) {
    إذا (ع == ٠) { ارجع "٠" }
    متغير نص = ""
    من_أجل (ي من ١ إلى ع) {
        إذا (ع % ٢ == ٠) { نص = "٠" + نص }
        وإلا { نص = "١" + نص }
        ع = ع // ٢
    }
    ارجع نص
}
```

